DROP TABLE IF EXISTS `System`;
CREATE TABLE `System` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `userId` bigint NOT NULL,
  `type` varchar(45) NOT NULL DEFAULT '0' COMMENT '类型：0 - Android OS, 1 - iOS, 3 - HarmonyOS, 4 - Tizen',
  `brand` varchar(45) NOT NULL COMMENT '品牌。Xiaomi MIUI, Meizu Flyme, Huawei HiOS, Huawei HornorOS, Apple iPad OS, Apple Watch OS 等',
  `versionCode` int NOT NULL COMMENT '版本号 int 值，不是名称。',
  `versionName` varchar(45) NOT NULL COMMENT '版本号名称',
  `time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `name` varchar(100) DEFAULT NULL COMMENT '名称',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
);

