DROP TABLE IF EXISTS `Flow`;
CREATE TABLE `Flow` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `userId` bigint NOT NULL,
  `name` varchar(100) NOT NULL COMMENT '名称',
